// Die komplette Mahnlogik steht bewusst in einem einzigen Code-Node und nicht
// verteilt auf mehrere IF-Nodes: Wer dafuer geradesteht (Buchhaltung, GF), muss
// die Regeln an einer Stelle nachlesen und aendern koennen, ohne den Canvas zu
// verstehen. Jede Zeile bekommt eine Aktion UND eine Begruendung - auch die,
// bei denen nichts passiert. Sonst sucht man spaeter, warum nicht gemahnt wurde.

const BETRAGSGRENZE_EUR = 5000;   // darueber entscheidet immer ein Mensch
const STUFEN = [
  { ab_tagen: 40, aktion: 'eskalation', stufe: 3 },
  { ab_tagen: 21, aktion: 'mahnung_1', stufe: 2 },
  { ab_tagen: 7,  aktion: 'erinnerung', stufe: 1 },
];

// Google Sheets liefert Datumswerte je nach Zellformat als TT.MM.JJJJ oder als
// ISO-String zurueck. Beide Varianten zulassen, sonst faellt die halbe Liste
// stillschweigend hinten runter.
function alsDatum(wert) {
  if (!wert) return null;
  const s = String(wert).trim();
  const de = s.match(/^(\d{1,2})\.(\d{1,2})\.(\d{4})$/);
  if (de) return new Date(Date.UTC(Number(de[3]), Number(de[2]) - 1, Number(de[1])));
  const d = new Date(s);
  return isNaN(d.getTime()) ? null : d;
}

// "1.234,56 EUR" ist Text, kein Betrag. Ohne diese Normalisierung vergleicht man
// Zeichenketten mit Zahlen und die Betragssperre greift nie.
function alsBetrag(wert) {
  if (typeof wert === 'number') return wert;
  const s = String(wert ?? '').replace(/[^0-9,.\-]/g, '');
  if (!s) return 0;
  return Number(s.replace(/\./g, '').replace(',', '.')) || 0;
}

function alsDeutschesDatum(d) {
  const t = String(d.getUTCDate()).padStart(2, '0');
  const m = String(d.getUTCMonth() + 1).padStart(2, '0');
  return t + '.' + m + '.' + d.getUTCFullYear();
}

const heute = new Date();
heute.setUTCHours(0, 0, 0, 0);
const raus = [];

for (const eintrag of $input.all()) {
  const p = eintrag.json;
  const faellig = alsDatum(p['Faelligkeitsdatum']);
  const offen = alsBetrag(p['Betrag']);
  const status = String(p['Status'] ?? '').toLowerCase();
  const bereitsGemahnt = Number(p['Letzte Mahnstufe'] ?? 0) || 0;
  const empfaenger = String(p['E-Mail'] ?? '').trim();

  let aktion = 'keine';
  let grund = '';
  let stufe = 0;
  let tage = null;

  if (!faellig) {
    grund = 'Kein oder unlesbares Faelligkeitsdatum';
  } else if (status.includes('bezahlt') || status.includes('storn') || status.includes('gutschrift')) {
    grund = 'Posten ist erledigt (' + (p['Status'] ?? '') + ')';
  } else if (offen <= 0) {
    grund = 'Kein offener Betrag';
  } else {
    tage = Math.floor((heute.getTime() - faellig.getTime()) / 86400000);
    const treffer = STUFEN.find((s) => tage >= s.ab_tagen);
    if (!treffer) {
      grund = tage < 0
        ? 'Noch ' + Math.abs(tage) + ' Tage bis zur Faelligkeit'
        : 'Erst ' + tage + ' Tage ueberfaellig, die Staffel beginnt bei 7';
    } else if (treffer.stufe <= bereitsGemahnt) {
      // Ohne diese Sperre laeuft jeden Morgen dieselbe Mahnung raus - der
      // sicherste Weg, einen zahlenden Kunden zu verlieren.
      grund = 'Stufe ' + treffer.stufe + ' wurde bereits versendet';
    } else {
      stufe = treffer.stufe;
      aktion = treffer.aktion;
    }
  }

  let intern_grund = '';
  if (aktion !== 'keine') {
    if (offen > BETRAGSGRENZE_EUR) {
      // Harte Sperre: eine falsch adressierte Mahnung ueber 5.000 EUR kostet
      // mehr Kundenbeziehung, als sie an Verzugszinsen einbringt.
      aktion = 'intern';
      intern_grund = 'Offener Betrag ueber der Automatikgrenze von ' + BETRAGSGRENZE_EUR + ' EUR - bitte persoenlich klaeren, keine Automatik-Mahnung.';
    } else if (aktion === 'eskalation') {
      aktion = 'intern';
      intern_grund = tage + ' Tage ueberfaellig. Stufe 3 bedeutet zweite Mahnung, Ratenvereinbarung oder Inkasso - das entscheidet die Geschaeftsfuehrung, nicht der Workflow.';
    } else if (!empfaenger.includes('@')) {
      aktion = 'intern';
      intern_grund = 'Keine gueltige E-Mail-Adresse im offenen Posten hinterlegt - Versand nur per Post moeglich.';
    }
  }

  raus.push({
    json: {
      rechnungsnummer: String(p['Rechnungsnummer'] ?? '').trim(),
      kunde: String(p['Kunde'] ?? '').trim(),
      empfaenger,
      betrag_eur: Number(offen.toFixed(2)),
      betrag_formatiert: offen.toLocaleString('de-DE', { minimumFractionDigits: 2, maximumFractionDigits: 2 }),
      faellig_am: faellig ? alsDeutschesDatum(faellig) : null,
      tage_ueberfaellig: tage,
      mahnstufe: stufe,
      aktion,
      grund,
      intern_grund,
      geprueft_am: alsDeutschesDatum(heute),
    },
  });
}

return raus;

